import{_ as a,o as s,c as t,a0 as n}from"./chunks/framework.BdekkmWZ.js";const h=JSON.parse('{"title":"路由守卫 (Router Guard) 工厂式重构设计规格 (2026-09-14)","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-09-14-router-guard-design.md","filePath":"superpowers/specs/2026-09-14-router-guard-design.md"}'),o={name:"superpowers/specs/2026-09-14-router-guard-design.md"};function d(r,e,c,p,i,l){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="路由守卫-router-guard-工厂式重构设计规格-2026-09-14" tabindex="-1">路由守卫 (Router Guard) 工厂式重构设计规格 (2026-09-14) <a class="header-anchor" href="#路由守卫-router-guard-工厂式重构设计规格-2026-09-14" aria-label="Permalink to &quot;路由守卫 (Router Guard) 工厂式重构设计规格 (2026-09-14)&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>当前 <a href="https://github.com/cq112233/unibestX/blob/main/src/router/interceptor.uts" target="_blank" rel="noreferrer">src/router/interceptor.uts</a> 把 URL 解析、路径规范化、相对路径解析、Token 校验、白/黑名单裁决、登录页重定向等全部逻辑塞在单个 <code>doIntercept()</code> 里，四个跳转 API 各自薄薄包一层。任何新增一条路由规则都要改动这个 260 行的单体函数，且无法单测。</p><p>本设计参照 <code>/Users/chenqi/Documents/qizhi-front/qizhi-h5/src/router/guard</code> 的<strong>工厂式守卫模式</strong>（一个关切一个文件，<code>createXxx(router)</code> 工厂 + <code>setupRouterGuard(router)</code> 统一安装），把 <code>doIntercept()</code> 拆解为可插拔的守卫链。</p><p><strong>目标</strong>：</p><ul><li>行为与现有实现<strong>完全等价</strong>，零回归；</li><li>新增路由规则 = 新增一个 <code>createXxxGuard.uts</code> + 在 <code>setupRouterGuard()</code> 里注册一行；</li><li>守卫裁决逻辑与平台 API 解耦，可在 node 里跑决策矩阵测试。</li></ul><hr><h2 id="_2-参考模式映射" tabindex="-1">2. 参考模式映射 <a class="header-anchor" href="#_2-参考模式映射" aria-label="Permalink to &quot;2. 参考模式映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>qizhi-h5 (vue-router)</th><th>本项目 (uni-app X)</th><th>说明</th></tr></thead><tbody><tr><td><code>setupRouterGuard(router)</code></td><td><code>setupRouterGuard()</code></td><td>无 router 实例，守卫注册进模块级注册表</td></tr><tr><td><code>router.beforeEach(fn)</code></td><td><code>RouteGuard.beforeEach</code></td><td>工厂函数返回守卫对象</td></tr><tr><td><code>router.afterEach(fn)</code></td><td><code>RouteGuard.afterEach</code> + interceptor <code>success</code> 回调</td><td>见 6.2 风险</td></tr><tr><td><code>next()</code></td><td><code>allow()</code></td><td>放行</td></tr><tr><td><code>next(&#39;/login&#39;)</code></td><td><code>block(&#39;/login&#39;)</code>，由 interceptor 派发</td><td>守卫只表达意图，不直接调 uni API</td></tr><tr><td><code>to.meta.title</code></td><td>无</td><td>本项目不做自动标题（见 3.4）</td></tr></tbody></table><p><strong>核心差异</strong>：<code>uni.addInterceptor</code> 的 <code>invoke</code> 必须<strong>同步</strong>返回 boolean，而 vue-router 的 <code>beforeEach</code> 可以是 async。因此本项目的守卫<strong>只能是同步的</strong>。</p><hr><h2 id="_3-架构设计" tabindex="-1">3. 架构设计 <a class="header-anchor" href="#_3-架构设计" aria-label="Permalink to &quot;3. 架构设计&quot;">​</a></h2><h3 id="_3-1-目录结构与依赖方向" tabindex="-1">3.1 目录结构与依赖方向 <a class="header-anchor" href="#_3-1-目录结构与依赖方向" aria-label="Permalink to &quot;3.1 目录结构与依赖方向&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/router/</span></span>
<span class="line"><span>├── location.uts                 [新] URL 解析 / 规范化 / 相对路径解析 → buildRouteContext()</span></span>
<span class="line"><span>├── config.uts                   [改] 常量 + judgeIsExcludePath() + buildLoginRedirectUrl()</span></span>
<span class="line"><span>├── guard/</span></span>
<span class="line"><span>│   ├── types.uts                [新] RouteGuardContext / GuardResult / RouteGuard + allow()/block()</span></span>
<span class="line"><span>│   ├── createTokenGuard.uts     [新]</span></span>
<span class="line"><span>│   ├── createPageGuard.uts      [新]</span></span>
<span class="line"><span>│   ├── createAfterGuard.uts     [新]</span></span>
<span class="line"><span>│   └── index.uts                [新] 注册表 + 守卫链执行器 + setupRouterGuard()</span></span>
<span class="line"><span>├── interceptor.uts              [改] 瘦身：建上下文 → 跑守卫链 → 派发重定向 → 安装 interceptor</span></span>
<span class="line"><span>├── index.uts                    [改] +1 行转发</span></span>
<span class="line"><span>└── toLoginPage.uts              [不变]</span></span></code></pre></div><p><strong>依赖方向（严格单向，无环）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>guard/types.uts ──┬──&gt; location.uts ──┐</span></span>
<span class="line"><span>                  │                   ├──&gt; create*.uts ──&gt; guard/index.uts ──&gt; interceptor.uts</span></span>
<span class="line"><span>                  └──&gt; config.uts ────┘</span></span></code></pre></div><ul><li><code>guard/types.uts</code> <strong>零依赖</strong>，是打破环的关键：否则 <code>create*.uts</code> 需从 <code>guard/index.uts</code> 取类型，而 <code>guard/index.uts</code> 又要 import <code>create*.uts</code>，成环。</li><li><code>config.uts</code> <strong>只依赖 <code>guard/types.uts</code></strong>，其余保持纯叶子：<code>buildLoginRedirectUrl()</code> 接收已序列化的 <code>fullPath: string</code>，序列化动作由 <code>location.uts</code> 的 <code>serializeTarget()</code> 承担。</li><li><code>guard/createPageGuard.uts</code> 不允许 import <code>interceptor.uts</code>（<code>judgeIsExcludePath</code> 因此迁至 <code>config.uts</code>）。</li></ul><h3 id="_3-2-核心接口-guard-types-uts" tabindex="-1">3.2 核心接口（<code>guard/types.uts</code>） <a class="header-anchor" href="#_3-2-核心接口-guard-types-uts" aria-label="Permalink to &quot;3.2 核心接口（\`guard/types.uts\`）&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/** 路由目标：一次跳转的目标或来源 */</span></span>
<span class="line"><span>export type RouteTarget = {</span></span>
<span class="line"><span>  /** 原始 url 字符串（保留 query） */</span></span>
<span class="line"><span>  url: string;</span></span>
<span class="line"><span>  /** 规范化路径（带前导 /，不含 query） */</span></span>
<span class="line"><span>  path: string;</span></span>
<span class="line"><span>  /** 查询参数键值对 */</span></span>
<span class="line"><span>  query: Map&lt;string, string&gt;;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 路由守卫上下文 */</span></span>
<span class="line"><span>export type RouteGuardContext = {</span></span>
<span class="line"><span>  /** 目标页面 */</span></span>
<span class="line"><span>  to: RouteTarget;</span></span>
<span class="line"><span>  /** 来源页面（当前栈顶页面） */</span></span>
<span class="line"><span>  from: RouteTarget;</span></span>
<span class="line"><span>  /** 触发本次跳转的 API：navigateTo / redirectTo / reLaunch / switchTab */</span></span>
<span class="line"><span>  api: string;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 守卫裁决结果 */</span></span>
<span class="line"><span>export type GuardResult = {</span></span>
<span class="line"><span>  /** 是否放行 */</span></span>
<span class="line"><span>  pass: boolean;</span></span>
<span class="line"><span>  /** 拦截时可选：需要改跳的目标 url；null 表示静默拦截 */</span></span>
<span class="line"><span>  redirect: string | null;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 单个路由守卫 */</span></span>
<span class="line"><span>export type RouteGuard = {</span></span>
<span class="line"><span>  /** 守卫名，仅用于日志排查 */</span></span>
<span class="line"><span>  name: string;</span></span>
<span class="line"><span>  /** 前置守卫：返回 pass=false 即短路整条链 */</span></span>
<span class="line"><span>  beforeEach: ((ctx: RouteGuardContext) =&gt; GuardResult) | null;</span></span>
<span class="line"><span>  /** 后置守卫：仅在跳转成功后执行，不参与裁决 */</span></span>
<span class="line"><span>  afterEach: ((ctx: RouteGuardContext) =&gt; void) | null;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 构造放行裁决 */</span></span>
<span class="line"><span>export function allow(): GuardResult;</span></span>
<span class="line"><span>/** 构造拦截裁决；redirect 为 null 表示静默拦截 */</span></span>
<span class="line"><span>export function block(redirect: string | null = null): GuardResult;</span></span></code></pre></div><blockquote><p><code>type</code> 含函数字段在本项目已有先例：<a href="https://github.com/cq112233/unibestX/blob/main/src/utils/upload/index.uts" target="_blank" rel="noreferrer">src/utils/upload/index.uts</a> 的 <code>onProgress?: (progress: number) =&gt; void</code>。</p></blockquote><h3 id="_3-3-守卫链执行语义-guard-index-uts" tabindex="-1">3.3 守卫链执行语义（<code>guard/index.uts</code>） <a class="header-anchor" href="#_3-3-守卫链执行语义-guard-index-uts" aria-label="Permalink to &quot;3.3 守卫链执行语义（\`guard/index.uts\`）&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export function setupRouterGuard(): void {</span></span>
<span class="line"><span>  resetGuards();</span></span>
<span class="line"><span>  // 顺序即语义：tokenGuard 必须早于 pageGuard ——</span></span>
<span class="line"><span>  // 外部跳转携带 accessToken 时先落库，pageGuard 才能看到「已登录」状态，</span></span>
<span class="line"><span>  // 否则会被误判为未登录并重定向到登录页。</span></span>
<span class="line"><span>  registerGuard(createTokenGuard());</span></span>
<span class="line"><span>  registerGuard(createPageGuard());</span></span>
<span class="line"><span>  registerGuard(createAfterGuard());</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><code>runBeforeGuards(ctx)</code>：按注册顺序执行，<strong>任一返回 <code>pass: false</code> 立即短路</strong>并返回该裁决（对应 vue-router 中一个守卫 <code>next(&#39;/login&#39;)</code> 终结链条）。</li><li><code>runAfterGuards(ctx)</code>：全部执行，不短路、不影响导航结果。</li><li>该顺序约束与参考项目一致：qizhi 的 <code>guard/index.ts</code> 同样把「第三方登录」排在「页面权限拦截」之前。</li></ul><p><strong>afterEach 的上下文传递</strong>：interceptor 的 <code>success</code> 回调拿不到请求参数，无法还原 url。因此在 <code>guard/index.uts</code> 内维护一个模块级暂存：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export function setPendingAfterContext(ctx: RouteGuardContext): void;</span></span>
<span class="line"><span>export function runPendingAfterGuards(): void;   // 取出并清空暂存，再执行 runAfterGuards</span></span></code></pre></div><h3 id="_3-4-三个守卫" tabindex="-1">3.4 三个守卫 <a class="header-anchor" href="#_3-4-三个守卫" aria-label="Permalink to &quot;3.4 三个守卫&quot;">​</a></h3><h4 id="createpageguard-—-迁移-dointercept-主体-行为等价" tabindex="-1"><code>createPageGuard</code> — 迁移 <code>doIntercept</code> 主体，行为等价 <a class="header-anchor" href="#createpageguard-—-迁移-dointercept-主体-行为等价" aria-label="Permalink to &quot;\`createPageGuard\` — 迁移 \`doIntercept\` 主体，行为等价&quot;">​</a></h4><table tabindex="0"><thead><tr><th>登录态</th><th>策略</th><th>目标路径</th><th>裁决</th></tr></thead><tbody><tr><td>已登录</td><td>—</td><td>非登录页</td><td><code>allow()</code></td></tr><tr><td>已登录</td><td>—</td><td>登录页</td><td><code>block(redirect ?? 首页)</code></td></tr><tr><td>未登录</td><td>白名单</td><td>排除页 / 登录页</td><td><code>allow()</code></td></tr><tr><td>未登录</td><td>白名单</td><td>其余</td><td><code>block(登录页?redirect=原地址)</code></td></tr><tr><td>未登录</td><td>黑名单</td><td>排除页</td><td><code>block(登录页?redirect=原地址)</code></td></tr><tr><td>未登录</td><td>黑名单</td><td>其余</td><td><code>allow()</code></td></tr></tbody></table><h4 id="createtokenguard-—-url-携带-accesstoken-时写入-tokenstore" tabindex="-1"><code>createTokenGuard</code> — URL 携带 accessToken 时写入 tokenStore <a class="header-anchor" href="#createtokenguard-—-url-携带-accesstoken-时写入-tokenstore" aria-label="Permalink to &quot;\`createTokenGuard\` — URL 携带 accessToken 时写入 tokenStore&quot;">​</a></h4><p>从 <code>ctx.to.query</code> 取 <code>accessToken</code>，非空则调用 <code>useTokenStore().setSingleToken(...)</code>。</p><p><strong>约束</strong>：tokenStore 只有 <code>setSingleToken(res)</code> / <code>setDoubleToken(res)</code>，<strong>没有裸 token 的 setter</strong>（见 <a href="https://github.com/cq112233/unibestX/blob/main/src/store/vdom/token.uts#L122" target="_blank" rel="noreferrer">token.uts:122</a>）。因此复用既有的 <code>setSingleToken</code>：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setSingleToken({ token: accessToken, expiresIn: EXTERNAL_TOKEN_TTL_SECONDS } as ISingleTokenRes);</span></span></code></pre></div><p><code>EXTERNAL_TOKEN_TTL_SECONDS</code> 在 <code>config.uts</code> 中定义为 <code>7200</code>（2 小时）。<strong>取默认值而非真实有效期是刻意的</strong> —— URL 只携带 token 本身，不携带 <code>expiresIn</code>；该常量必须带注释说明这是占位语义，接入真实外部跳转方后应改为由对方传 <code>expiresIn</code>。</p><p><strong>本守卫不改动 <code>src/store/</code> 下任何文件。</strong></p><h4 id="createafterguard-—-只提供机制-内置一个实做示例" tabindex="-1"><code>createAfterGuard</code> — 只提供机制，内置一个实做示例 <a class="header-anchor" href="#createafterguard-—-只提供机制-内置一个实做示例" aria-label="Permalink to &quot;\`createAfterGuard\` — 只提供机制，内置一个实做示例&quot;">​</a></h4><p><code>afterEach</code> 执行 <code>setCurIdxByPath(ctx.to.path)</code> 同步自定义 TabBar 选中态。</p><p><strong>必要性</strong>：TabBar 策略 3（<code>CUSTOM_TABBAR_WITHOUT_NATIVE</code>）走 <code>uni.redirectTo</code> 跳转，不经过 <code>switchTabbar()</code>，选中态会失同步。</p><p><strong>明确不做自动导航栏标题</strong>：uni-app X 没有 vue-router 的 <code>to.meta.title</code>，而集中映射表与逐页 <code>defineRouteMeta</code> 都有各自成本，本次不引入。</p><hr><h2 id="_4-interceptor-uts-改造后形态" tabindex="-1">4. <code>interceptor.uts</code> 改造后形态 <a class="header-anchor" href="#_4-interceptor-uts-改造后形态" aria-label="Permalink to &quot;4. \`interceptor.uts\` 改造后形态&quot;">​</a></h2><p>保留四个 API 各自的 interceptor 对象（App 原生端需要按 <code>NavigateToOptions</code> / <code>RedirectToOptions</code> / <code>ReLaunchOptions</code> / <code>SwitchTabOptions</code> 分别强转），但 <code>invoke</code> 统一收敛：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/** 统一前置处理：构建上下文 → 跑守卫链 → 派发守卫裁决的重定向 */</span></span>
<span class="line"><span>function handleBefore(url: string, api: string): boolean {</span></span>
<span class="line"><span>  if (url == null || url == &#39;&#39;) return true;</span></span>
<span class="line"><span>  const ctx = buildRouteContext(url, api);       // location.uts 提供</span></span>
<span class="line"><span>  const result = runBeforeGuards(ctx);</span></span>
<span class="line"><span>  if (!result.pass) {</span></span>
<span class="line"><span>    dispatchRedirect(result.redirect, api);</span></span>
<span class="line"><span>    return false;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  setPendingAfterContext(ctx);</span></span>
<span class="line"><span>  return true;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 由「路由器」侧统一派发跳转，守卫本身不调 uni API */</span></span>
<span class="line"><span>function dispatchRedirect(url: string | null, api: string): void {</span></span>
<span class="line"><span>  // url 为 null/空 → 静默拦截，不做任何跳转</span></span>
<span class="line"><span>  // 命中 TabBar 页面 → switchTabbar(url)</span></span>
<span class="line"><span>  // 其余 → uni.navigateTo({ url })，与现有实现等价（不随触发本次跳转的 api 变化）</span></span>
<span class="line"><span>  // api 仅用于日志，便于排查「哪个跳转 API 触发了重定向」</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>与现有实现的等价性</strong>：原 <code>doIntercept</code> 在重定向时同样一律使用 <code>uni.navigateTo</code>（仅 TabBar 页面改走 <code>switchTabbar</code>），不区分是哪个 API 触发的。本次保持该行为不变，<code>api</code> 参数仅作日志用途。</p><p><code>installRouteInterceptor()</code> 内部先调 <code>setupRouterGuard()</code> 再 <code>uni.addInterceptor(...)</code>，因此 <a href="https://github.com/cq112233/unibestX/blob/main/main.uts" target="_blank" rel="noreferrer">main.uts</a> <strong>无需改动</strong>。</p><hr><h2 id="_5-红线遵守" tabindex="-1">5. 红线遵守 <a class="header-anchor" href="#_5-红线遵守" aria-label="Permalink to &quot;5. 红线遵守&quot;">​</a></h2><ul><li><strong>红线 21（多层 <code>export *</code> 套娃）</strong>：<code>guard/index.uts</code> <strong>不做 <code>export *</code></strong>，只导出自身符号（类型、注册表、执行器、<code>setupRouterGuard</code>）。<code>create*.uts</code> 由 <code>guard/index.uts</code> 以 <code>import</code> 引用而非 re-export。<code>router/index.uts</code> 单层转发 <code>./guard/index.uts</code>，全项目无两层转发链。</li><li><strong>禁止 <code>interface</code></strong>：全部使用 <code>type</code> 别名。</li><li><strong>禁止 <code>undefined</code></strong>：空值一律 <code>null</code>，联合类型仅为 <code>T | null</code>。</li><li><strong>基础类型等值比较</strong>：一律 <code>==</code> / <code>!=</code>，禁止 <code>===</code> / <code>!==</code>。</li><li><strong>下标读取</strong>：边界判断与读取写在同一个短路表达式内、判断在前（避免 Kotlin 侧越界抛异常而 H5 静默通过）。</li><li><strong>局部声明顺序</strong>：<code>&lt;script setup&gt;</code> 与 <code>.uts</code> 内的局部函数定义写在所有调用点之前（Kotlin 局部声明不提升）。</li></ul><hr><h2 id="_6-风险与约束" tabindex="-1">6. 风险与约束 <a class="header-anchor" href="#_6-风险与约束" aria-label="Permalink to &quot;6. 风险与约束&quot;">​</a></h2><h3 id="_6-1-守卫只能是同步的" tabindex="-1">6.1 守卫只能是同步的 <a class="header-anchor" href="#_6-1-守卫只能是同步的" aria-label="Permalink to &quot;6.1 守卫只能是同步的&quot;">​</a></h3><p><code>invoke</code> 必须同步返回 boolean，参考项目里 <code>await userStore.getUserInfo()</code> 那类异步守卫<strong>在本形态下写不出来</strong>。需要异步的场景须用「先拦截 + 异步完成后重新 dispatch」的模式。本次不实现，在 <code>types.uts</code> 注释中写清楚，避免后人误以为是遗漏。</p><h3 id="_6-2-aftereach-依赖-interceptor-的-success-回调" tabindex="-1">6.2 <code>afterEach</code> 依赖 interceptor 的 <code>success</code> 回调 <a class="header-anchor" href="#_6-2-aftereach-依赖-interceptor-的-success-回调" aria-label="Permalink to &quot;6.2 \`afterEach\` 依赖 interceptor 的 \`success\` 回调&quot;">​</a></h3><p>官方 uni-app x 文档的示例对象含 <code>invoke</code>/<code>success</code>/<code>fail</code>/<code>complete</code>，但未提供逐回调的平台兼容表。该回调在 App 原生端是否触发<strong>必须真机验证</strong>。</p><p>若不触发，退路是改由页面 <code>onShow</code> 兜底 —— <code>guard/index.uts</code> 是唯一改动点。</p><h3 id="_6-3-递归触发" tabindex="-1">6.3 递归触发 <a class="header-anchor" href="#_6-3-递归触发" aria-label="Permalink to &quot;6.3 递归触发&quot;">​</a></h3><p><code>dispatchRedirect</code> 内部调用 <code>uni.navigateTo</code> / <code>switchTabbar</code> 会再次触发 interceptor。现有实现已依赖此行为并靠「登录页放行」终止，本次保持等价，但需在回归矩阵中覆盖「已登录访问登录页」这一路径确认不无限循环。</p><hr><h2 id="_7-验证计划" tabindex="-1">7. 验证计划 <a class="header-anchor" href="#_7-验证计划" aria-label="Permalink to &quot;7. 验证计划&quot;">​</a></h2><h3 id="_7-1-node-harness-决策矩阵测试-先写-后实现" tabindex="-1">7.1 node harness 决策矩阵测试（先写，后实现） <a class="header-anchor" href="#_7-1-node-harness-决策矩阵测试-先写-后实现" aria-label="Permalink to &quot;7.1 node harness 决策矩阵测试（先写，后实现）&quot;">​</a></h3><p>项目<strong>当前没有任何测试框架</strong>（<code>package.json</code> 无 vitest/jest），因此按 skill 1.3.13 的做法搭建 node harness：</p><ol><li>将 <code>guard/types.uts</code>、<code>guard/createPageGuard.uts</code>、<code>location.uts</code>、<code>config.uts</code> 按纯文本转换复制为 <code>.ts</code>（相对导入补 <code>.ts</code> 后缀、条件编译按 App 分支求值）；</li><li><code>stub.ts</code> 补齐运行时全局：<code>uni</code>（<code>navigateTo</code> 等空实现）、<code>getCurrentPages</code>、<code>useTokenStore</code>（可注入登录态）；</li><li>跑 <code>createPageGuard</code> 的全决策矩阵：{已登录, 未登录} × {白名单模式, 黑名单模式} × {登录页, 排除页, 普通页} × {带 redirect, 不带 redirect}；</li><li><strong>必须验证「改回旧实现测试会红」</strong> —— 不会红的测试等于没测（红线 28）。</li></ol><p>harness 放在 <code>scripts/guard-test/</code>，不参与主工程编译。</p><h3 id="_7-2-真机构建验证" tabindex="-1">7.2 真机构建验证 <a class="header-anchor" href="#_7-2-真机构建验证" aria-label="Permalink to &quot;7.2 真机构建验证&quot;">​</a></h3><p>按 skill 1.3.15，<strong>必须使用不带 <code>--compile</code> 的真机构建</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/HBuilderX.app/Contents/MacOS/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-android</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Users/chenqi/Desktop/unibestX</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deviceId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">序列</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">号</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>构建后先确认日志中 <code>编译为android class</code> 出现 <strong>≥ 1 次</strong>，再看 <code>项目 unibestX 编译成功。</code></p><p>（<code>launch app-android --compile true</code> 与 <code>compile app-android --file</code> 都<strong>不执行</strong> Kotlin 编译阶段，对故意写坏的代码同样报「编译成功」，不可作为验证依据。）</p><h3 id="_7-3-手工回归矩阵" tabindex="-1">7.3 手工回归矩阵 <a class="header-anchor" href="#_7-3-手工回归矩阵" aria-label="Permalink to &quot;7.3 手工回归矩阵&quot;">​</a></h3><p>4 个跳转 API × {已登录, 未登录} × {登录页, 白名单页, 普通页}，重点覆盖：</p><ul><li>已登录访问登录页 → 重定向到 <code>redirect</code> 或首页，且不无限循环；</li><li>未登录访问白名单页 → 放行；</li><li>未登录访问普通页 → 重定向登录页且携带完整 <code>redirect</code>（含原 query）；</li><li>TabBar 策略 3 下跳转 TabBar 页面 → <code>curIdx</code> 选中态同步正确（验证 <code>createAfterGuard</code>）。</li></ul><hr><h2 id="_8-交付清单" tabindex="-1">8. 交付清单 <a class="header-anchor" href="#_8-交付清单" aria-label="Permalink to &quot;8. 交付清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>动作</th></tr></thead><tbody><tr><td><code>src/router/location.uts</code></td><td>新增</td></tr><tr><td><code>src/router/config.uts</code></td><td>修改：新增 <code>judgeIsExcludePath()</code>、<code>buildLoginRedirectUrl()</code>、外部 token 默认有效期常量</td></tr><tr><td><code>src/router/guard/types.uts</code></td><td>新增</td></tr><tr><td><code>src/router/guard/createTokenGuard.uts</code></td><td>新增</td></tr><tr><td><code>src/router/guard/createPageGuard.uts</code></td><td>新增</td></tr><tr><td><code>src/router/guard/createAfterGuard.uts</code></td><td>新增</td></tr><tr><td><code>src/router/guard/index.uts</code></td><td>新增</td></tr><tr><td><code>src/router/interceptor.uts</code></td><td>修改：瘦身</td></tr><tr><td><code>src/router/index.uts</code></td><td>修改：+1 行转发</td></tr><tr><td><code>scripts/guard-test/</code></td><td>新增：node harness 测试</td></tr></tbody></table>`,73)])])}const g=a(o,[["render",d]]);export{h as __pageData,g as default};
